import { createWorkflowChain } from '@voltagent/core';
import { openai } from '@ai-sdk/openai';

export const parallelWorkflow = createWorkflowChain({
  id: 'parallel-analysis-workflow',
  inputSchema: {
    type: 'object',
    properties: {
      text: {
        type: 'string',
        description: 'The input text to analyze'
      }
    },
    required: ['text']
  },
  steps: [
    {
      id: 'parallel-analysis',
      andAll: [
        {
          id: 'sentiment-analysis',
          andAgent: {
            model: openai('gpt-4o'),
            prompt: 'Analyze the sentiment of the following text. Return a JSON object with "sentiment" (positive/negative/neutral) and "confidence" (0-1). Text: {{text}}',
            outputSchema: {
              type: 'object',
              properties: {
                sentiment: { type: 'string' },
                confidence: { type: 'number' }
              }
            }
          }
        },
        {
          id: 'topic-categorization',
          andAgent: {
            model: openai('gpt-4o'),
            prompt: 'Categorize the topic of the following text. Return a JSON object with "topic" (main category) and "subtopics" (array of subtopics). Text: {{text}}',
            outputSchema: {
              type: 'object',
              properties: {
                topic: { type: 'string' },
                subtopics: { type: 'array', items: { type: 'string' } }
              }
            }
          }
        }
      ]
    }
  ]
});

