import { createWorkflowChain } from '@voltagent/core';
import { openai } from '@ai-sdk/openai';
import { generateObject } from 'ai';
import { z } from 'zod';

export const parallelWorkflow = createWorkflowChain({
  id: 'parallel-analysis-workflow',
  name: 'Parallel Analysis Workflow',
  purpose: 'Perform parallel analysis of input text',
  input: z.object({
    text: z.string()
  }),
  result: z.object({
    sentiment: z.object({
      sentiment: z.string(),
      confidence: z.number()
    }),
    topic: z.object({
      topic: z.string(),
      subtopics: z.array(z.string())
    })
  })
})
.andAll({
  id: 'parallel-analysis',
  steps: [
    {
      id: 'sentiment-analysis',
      execute: async ({ data }) => {
        const result = await generateObject({
          model: openai('gpt-4o'),
          schema: z.object({
            sentiment: z.enum(['positive', 'negative', 'neutral']),
            confidence: z.number().min(0).max(1)
          }),
          prompt: `Analyze the sentiment of the following text. Return a JSON object with "sentiment" (positive/negative/neutral) and "confidence" (0-1). Text: ${data.text}`
        });
        return { sentiment: result.object };
      }
    },
    {
      id: 'topic-categorization',
      execute: async ({ data }) => {
        const result = await generateObject({
          model: openai('gpt-4o'),
          schema: z.object({
            topic: z.string(),
            subtopics: z.array(z.string())
          }),
          prompt: `Categorize the topic of the following text. Return a JSON object with "topic" (main category) and "subtopics" (array of subtopics). Text: ${data.text}`
        });
        return { topic: result.object };
      }
    }
  ]
})
.andThen({
  id: 'combine-results',
  execute: async ({ data }) => {
    // data is an array: [{ sentiment }, { topic }]
    return {
      sentiment: data[0].sentiment,
      topic: data[1].topic
    };
  }
});

