import { createWorkflowChain } from '@voltagent/core';
import { z } from 'zod';

export const parallelWorkflow = createWorkflowChain({
  id: 'parallel-analysis-workflow',
  name: 'Parallel Analysis Workflow',
  purpose: 'Perform parallel analysis of input text',
  input: z.object({
    text: z.string()
  }),
  result: z.object({
    sentiment: z.string(),
    confidence: z.number(),
    topic: z.string(),
    subtopics: z.array(z.string())
  })
})
.andAll({
  id: 'parallel-analysis',
  steps: [
    {
      id: 'sentiment-analysis',
      execute: async ({ data }) => {
        // Simulate sentiment analysis
        return { 
          sentiment: 'positive', 
          confidence: 0.95 
        };
      }
    },
    {
      id: 'topic-categorization',
      execute: async ({ data }) => {
        // Simulate topic categorization
        return { 
          topic: 'Technology', 
          subtopics: ['AI', 'Productivity', 'Software'] 
        };
      }
    }
  ]
})
.andThen({
  id: 'combine-results',
  execute: async ({ data }) => {
    // data is an array: [{ sentiment, confidence }, { topic, subtopics }]
    return {
      ...data[0],
      ...data[1]
    };
  }
});

