  id: 'parallel-analysis-workflow',
  name: 'Parallel Analysis Workflow',
  purpose: 'Perform parallel analysis of input text',
  input: z.object({
    text: z.string()
  }),
  result: z.object({
    sentiment: z.string()
  })
})
.andAll({
  id: 'parallel-analysis',
  steps: [
    {
      id: 'sentiment-analysis',
      execute: async ({ data }) => {
        // Simulate sentiment analysis
        return { 
          sentiment: 'positive'
        };
      }
    }
  ]
});

