import { createWorkflowChain, andThen } from '@voltagent/core';
import { z } from 'zod';

export const parallelWorkflow = createWorkflowChain({
  id: 'parallel-analysis-workflow',
  name: 'Parallel Analysis Workflow',
  purpose: 'Perform parallel analysis of input text',
  input: z.object({
    text: z.string()
  }),
  result: z.any()
})
.andAll({
  id: 'parallel-analysis',
  steps: [
    andThen({
      id: 'sentiment-analysis',
      execute: async ({ data }) => {
        console.log('Executing sentiment analysis with data:', data);
        // Simulate sentiment analysis
        return { 
          sentiment: 'positive'
        };
      }
    }),
    andThen({
      id: 'topic-categorization',
      execute: async ({ data }) => {
        console.log('Executing topic categorization with data:', data);
        // Simulate topic categorization
        return { 
          topic: 'Technology'
        };
      }
    })
  ]
});

